\title{Excluded Minors for $\Zn$-Gainable Biased Graphs:\\ The Parallel-Class Slice and a Divisibility Monotonicity Law}
\author{Aristotle (Harmonic)}
\date{2026-06-28}

\begin{document}
\begin{abstract}
A \emph{biased graph} records, for each cycle of an underlying graph, whether that cycle is \emph{balanced}. A \emph{gain labelling} valued in an additive abelian group $A$ assigns a group element to each edge; it \emph{realises} the biased graph when a cycle is balanced if and only if the signed sum of its edge labels vanishes. The graph is \emph{gainable over $A$} when such a labelling exists, and $\Zn$-\emph{gainable} when $A=\Zn$. The Zaslavsky/Funk conjecture predicts that for every $n\ge 2$ a biased graph is $\Zn$-gainable iff it contains none of the minors $(n{+}1)K_2$, $\pm K_3$, or $-K_4$. We give a complete treatment of the \emph{parallel-class (digon) slice} of this conjecture over an arbitrary finite cyclic group $\Zn$, $n\ge 2$, whose unique excluded minor is $(n{+}1)K_2$. We remove the primality hypothesis of prior work; we establish a monotonicity principle that gainability is preserved by injective additive homomorphisms of the gain group; and specialising to cyclic groups we obtain the \emph{divisibility law}: $m\mid n$ implies every $\Zm$-gainable graph is $\Zn$-gainable. The characterization reduces both gainability and the presence of a $(n{+}1)K_2$ minor to a single invariant, the number of balance classes, separated by complementary thresholds. All results are formalised and machine-checked.
\end{abstract}
\maketitle

\section{Introduction}

Biased graphs, introduced by Zaslavsky, abstract the combinatorial content shared by signed graphs, gain graphs, and the frame matroids and Dowling geometries built from them. A gain graph---edges labelled by group elements, a cycle balanced when its signed sum is the identity---is the prototypical source of a biased graph, and the central representability question asks whether an abstract biased graph arises from a gain labelling valued in a fixed group.

For a fixed finite cyclic group $\Zn$ this is the question of $\Zn$-gainability. Since gainability is minor-closed, one seeks an \emph{excluded-minor characterization}. The conjectured list for $\Zn$ is
\[ \{(n{+}1)K_2,\ \pm K_3,\ -K_4\}, \]
where $(n{+}1)K_2$ is the $(n{+}1)$-fold parallel edge with all digons unbalanced, and $\pm K_3$, $-K_4$ are fixed signed-graph configurations on three and four vertices.

\medskip\noindent\textbf{Contributions.}
\begin{enumerate}
\item \emph{Primality elimination.} The parallel-class case, previously available only for prime $n$, uses only $|\Zn|=n$, never any arithmetic property of $n$.
\item \emph{Monotonicity under injective homomorphisms} (\texttt{gainableBy\_of\_injective\_hom}): an injective additive homomorphism $A\hookrightarrow B$ transports gainability from $A$ to $B$.
\item \emph{The divisibility law} (\texttt{gainable\_mono\_of\_dvd}): $m\mid n$ implies every $\Zm$-gainable graph is $\Zn$-gainable, via an explicit injective homomorphism $\Zm\hookrightarrow\Zn$.
\item \emph{The parallel-class characterization} (\texttt{digon\_excluded\_minor}): for any parallel-class biased graph, $\Zn$-gainability is equivalent to the absence of a $(n{+}1)K_2$ minor, for every $n\ge 2$.
\end{enumerate}

\section{Definitions}
Throughout $E,F$ denote edge types and $A,B$ additive abelian groups.

\begin{definition}[signedSum]
An \emph{oriented closed walk} is a list $c$ of pairs $(e,b)$ with $e\in E$ an edge and $b\in\{\true,\false\}$ a direction. For $g:E\to A$,
\[ \ssum(g,c)=\sum_{(e,b)\in c}\begin{cases} g(e) & b=\true,\\ -g(e) & b=\false.\end{cases} \]
\end{definition}

\begin{definition}[BiasedGraph]
A biased graph on $E$ is a pair of predicates $\isCycle,\balanced:\mathrm{List}(E\times\mathrm{Bool})\to\mathrm{Prop}$. This cycle-only model discards the vertex set, retaining exactly the data constrained by the gain condition.
\end{definition}

\begin{definition}[GainableBy, Gainable]
$G$ is \emph{gainable over $A$} if there is $g:E\to A$ with, for every cycle $c$, $\ G.\balanced(c)\iff \ssum(g,c)=0$. It is $\Zn$-gainable, $\Gainable(n,G)$, when gainable over $\Zn$.
\end{definition}

\begin{definition}[mapCycle, pullGain, IsMinor]
For $\varphi:E\to F$ and $\sigma:E\to\mathrm{Bool}$, $\ \mapCycle(\varphi,\sigma,c)=\operatorname{map}(\lambda(e,b).(\varphi(e),\sigma(e)\oplus b))\,c$, and $\pullGain(\varphi,\sigma,g)(e)=$ if $\sigma(e)$ then $-g(\varphi(e))$ else $g(\varphi(e))$.
$H$ on $E$ is a \emph{labelled minor} of $G$ on $F$ if there exist $\varphi$ injective and $\sigma$ such that for every cycle $c$ of $H$, $\mapCycle(\varphi,\sigma,c)$ is a cycle of $G$ and $H.\balanced(c)\iff G.\balanced(\mapCycle(\varphi,\sigma,c))$.
\end{definition}

\begin{definition}[parallelEdges, digonGraph]
$\mathrm{parallelEdges}(n)$ on $\Fin n$ has cycles the digons $[(i,\true),(j,\false)]$, $i\ne j$, none balanced; the obstruction is $(n{+}1)K_2=\mathrm{parallelEdges}(n+1)$. For an equivalence relation $s$ on $E$, $\mathrm{digonGraph}(s)$ has the same digon cycles, with $[(i,\true),(j,\false)]$ balanced iff $s$ relates $i,j$.
\end{definition}

\section{Transport theory}

\begin{lemma}[signedSum\_addHom]\label{lem:addhom}
For an additive homomorphism $f:A\to_+B$, $\ \ssum(f\circ g,c)=f(\ssum(g,c))$.
\end{lemma}
\begin{proof}[Proof sketch]
$f$ preserves list sums and $f(-x)=-f(x)$, so applying $f$ termwise to the signed list and summing equals summing then applying $f$. Formally: rewrite by \texttt{map\_list\_sum}, \texttt{List.map\_map}, then \texttt{List.map\_congr\_left} and case-split on $b$.
\end{proof}

\begin{lemma}[signedSum\_mapCycle]\label{lem:mapcycle}
$\ssum(\pullGain(\varphi,\sigma,g),c)=\ssum(g,\mapCycle(\varphi,\sigma,c))$.
\end{lemma}
\begin{proof}[Proof sketch]
Compare termwise over $c$; a four-way case split on $(\sigma(e),b)$ shows the negation in $\pullGain$ exactly compensates the xor orientation flip, so signs agree.
\end{proof}

\begin{theorem}[gainableBy\_of\_isMinor]\label{thm:minorclosed}
If $G$ is gainable over $A$ and $H$ is a minor of $G$, then $H$ is gainable over $A$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $g$ realise $G$ and $(\varphi,\sigma)$ witness the minor. Put $g'=\pullGain(\varphi,\sigma,g)$. For a cycle $c$ of $H$, chain the minor's balance equivalence, the realisation of $G$, and Lemma~\ref{lem:mapcycle}: $H.\balanced(c)\iff\ssum(g',c)=0$.
\end{proof}

\begin{theorem}[gainableBy\_of\_injective\_hom]\label{thm:inj}
If $f:A\to_+B$ is injective and $G$ is gainable over $A$, then $G$ is gainable over $B$.
\end{theorem}
\begin{proof}[Proof sketch]
Take $g$ realising $G$ over $A$ and set $g_B=f\circ g$. By Lemma~\ref{lem:addhom}, $\ssum(g_B,c)=f(\ssum(g,c))$, and since $f$ is injective with $f(0)=0$, this vanishes iff $\ssum(g,c)=0$. Hence $g_B$ realises $G$ over $B$.
\end{proof}

\section{The divisibility law}

\begin{lemma}[exists\_injective\_zmod\_addHom\_of\_dvd]\label{lem:embed}
If $m\mid n$ there is an injective additive homomorphism $\Zm\to_+\Zn$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $n=mk$. Multiplication by $k$ induces $\iota:\Zm\to\Zn$, $[j]\mapsto[jk]$ (well defined since $m\mid(j-j')\Rightarrow n\mid(j-j')k$). If $[jk]=0$ in $\Zn$ then $mk\mid jk$, so $m\mid j$; the kernel is trivial, giving injectivity.
\end{proof}

\begin{theorem}[gainable\_mono\_of\_dvd]\label{thm:dvd}
If $m\mid n$ then $\Gainable(m,G)\Rightarrow\Gainable(n,G)$.
\end{theorem}
\begin{proof}
Combine Lemma~\ref{lem:embed} with Theorem~\ref{thm:inj}.
\end{proof}

\begin{remark}
For $m=3,n=12$ the embedding sends $0,1,2\mapsto 0,4,8$. The law is about divisibility, not size: $\mathbb{Z}/3$ has no homomorphic embedding into $\mathbb{Z}/4$ even though $3<4$.
\end{remark}

\section{The obstruction $(n{+}1)K_2$}

\begin{theorem}[parallelEdges\_not\_gainable]\label{thm:obstr}
For every $n\ge 2$, $(n{+}1)K_2$ is not $\Zn$-gainable.
\end{theorem}
\begin{proof}[Proof sketch]
A realising $g:\Fin(n+1)\to\Zn$ would, on each unbalanced digon $[(i,\true),(j,\false)]$, force $g(i)-g(j)\ne 0$, i.e.\ $g$ injective on $n+1$ elements into a set of size $n$---impossible by pigeonhole. Only $|\Zn|=n$ is used; primality is irrelevant.
\end{proof}

\begin{theorem}[not\_isMinor\_parallelEdges\_of\_gainable]\label{thm:nec}
Any $\Zn$-gainable biased graph contains no $(n{+}1)K_2$ minor.
\end{theorem}
\begin{proof}
A $(n{+}1)K_2$ minor would be gainable by Theorem~\ref{thm:minorclosed}, contradicting Theorem~\ref{thm:obstr}.
\end{proof}

\section{The parallel-class characterization}

\begin{lemma}[digon\_gainable\_iff\_realises]\label{lem:real}
$\mathrm{digonGraph}(s)$ is gainable over $\Zn$ iff there is $g:E\to\Zn$ with $s(i,j)\iff g(i)=g(j)$.
\end{lemma}
\begin{proof}[Proof sketch]
The digon $[(i,\true),(j,\false)]$ has signed sum $g(i)-g(j)$, zero iff $g(i)=g(j)$, and is balanced iff $s(i,j)$; the case $i=j$ holds trivially.
\end{proof}

\begin{theorem}[digon\_gainable\_iff\_card]\label{thm:gcard}
For finite $E$, $\ \Gainable(n,\mathrm{digonGraph}(s))\iff |\Quot(s)|\le n$.
\end{theorem}
\begin{proof}[Proof sketch]
$(\Rightarrow)$ The $g$ of Lemma~\ref{lem:real} descends to an injection $\Quot(s)\to\Zn$, so $|\Quot(s)|\le n$. $(\Leftarrow)$ An injection $\bar g:\Quot(s)\to\Zn$ gives $g(e)=\bar g([e])$ with $g(i)=g(j)\iff s(i,j)$.
\end{proof}

\begin{theorem}[digon\_isMinor\_iff\_card]\label{thm:mcard}
$\IsMinor((n{+}1)K_2,\mathrm{digonGraph}(s))\iff n+1\le|\Quot(s)|$.
\end{theorem}
\begin{proof}[Proof sketch]
$(\Rightarrow)$ A minor witness makes $i\mapsto[\varphi(i)]$ an injection $\Fin(n+1)\to\Quot(s)$. $(\Leftarrow)$ An injection $\psi:\Fin(n+1)\to\Quot(s)$, with $\varphi(i)$ a representative of $\psi(i)$ and $\sigma\equiv\false$, sends each unbalanced digon to an unbalanced digon.
\end{proof}

\begin{theorem}[digon\_excluded\_minor]\label{thm:main}
For finite $E$ and $n\ge 2$,
\[ \Gainable(n,\mathrm{digonGraph}(s))\iff \neg\,\IsMinor((n{+}1)K_2,\mathrm{digonGraph}(s)). \]
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:gcard} the left side is $|\Quot(s)|\le n$; by Theorem~\ref{thm:mcard} the minor condition is $n+1\le|\Quot(s)|$, whose negation is $|\Quot(s)|\le n$.
\end{proof}

\section{Discussion}
The cycle-only model captures $(n{+}1)K_2$, a pure counting obstruction, but is provably blind to $\pm K_3$ and $-K_4$, whose contradictions live in how incident triangles share vertices; detecting them needs an incidence-aware model. Two complementary phenomena emerge: the $(n{+}1)K_2$ obstruction is uniform and primality-free, depending on $n$ only through $|\Zn|=n$; whereas the relationship between moduli is genuinely arithmetic, climbing monotonically along the divisibility lattice via $\Zm\hookrightarrow\Zn$.

\section{Future Directions}
\begin{conjecture}[C1]
For every $n\ge2$, a biased graph is $\Zn$-gainable iff it avoids $(n{+}1)K_2$, $\pm K_3$, $-K_4$. The counting part is closed and $n$-uniform; the frontier is the fixed set $\{\pm K_3,-K_4\}$.
\end{conjecture}
\begin{conjecture}[C2]
A vertexed biased-graph model with explicit incidence makes $\pm K_3$, $-K_4$ first-class excluded minors detectable by a local certificate.
\end{conjecture}
\begin{conjecture}[C3]
$n\mapsto\{\text{graphs gainable over }\Zn\}$ is a lattice homomorphism from $(\mathbb{N}_{\ge1},\mid)$ to the powerset lattice, with the $\mathrm{lcm}$ step from $\mathbb{Z}/\mathrm{lcm}\hookrightarrow\Zm\times\mathbb{Z}/k$.
\end{conjecture}
\begin{conjecture}[C4]
For $m\nmid n$ with $m,n\ge2$ there is a biased graph gainable over $\Zm$ but not over $\Zn$, showing strictness.
\end{conjecture}

\section{Conclusion}
For every $n\ge2$, prime or composite, the parallel-class slice of the Zaslavsky/Funk conjecture holds with the single excluded minor $(n{+}1)K_2$, and gainability is monotone along divisibility via explicit group embeddings. The remaining frontier is isolated to two fixed small minors requiring an incidence-aware model.

